function getDatabaseUrl() {
  if (!fs.existsSync(envPath)) {
    return null;
  }
  try {
    const content = fs.readFileSync(envPath, 'utf8');
    const lines = content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('DATABASE_URL=')) {
        // Remove quotes if present
        let val = trimmed.substring('DATABASE_URL='.length).trim();
        if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
          val = val.slice(1, -1);
        }
        return val;
      }
    }
  } catch (error) {
    console.error('Error reading .env.test file:', error.message);
  }
  return null;
}

function runMigrations() {
  const dbUrl = getDatabaseUrl();
  if (!dbUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Parse the URL to log a safe, masked connection message
  try {
    const parsedUrl = new URL(dbUrl);
    const maskedUrl = `${parsedUrl.protocol}//${parsedUrl.username}:******@${parsedUrl.host}${parsedUrl.pathname}`;
    console.log(`Connected successfully to database: ${maskedUrl}`);
  } catch (e) {
    // Fallback if URL parsing fails
    console.log('Connected successfully to database.');
