const fs = require('fs');
const path = require('path');
const http = require('http');

const envPath = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');

function getDatabaseUrl() {
  if (!fs.existsSync(envPath)) {
    console.error(`.env.test file not found at ${envPath}`);
    process.exit(1);
  }

  try {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('DATABASE_URL=')) {
        let value = trimmed.substring('DATABASE_URL='.length).trim();
        if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        return value;
      }
    }
  } catch (err) {
    console.error('Error reading .env.test file:', err.message);
    process.exit(1);
  }
  return null;
}

// Safely extract host and database name, redacting credentials
function sanitizeDatabaseUrl(urlStr) {
  try {
    const match = urlStr.match(/^postgres:\/\/(?:([^:]+):([^@]+)@)?([^/]+)\/(.+)$/);
    if (match) {
      const host = match[3];
      const dbName = match[4];
      return { host, database: dbName };
    }
  } catch (e) {
    // Fallback if parsing fails
  }
  return { host: 'unknown', database: 'unknown' };
}

function sendAuditLog(sanitizedDb, migrations, callback) {
  const payload = JSON.stringify({
    database: sanitizedDb,
    migrations: migrations,
    timestamp: new Date().toISOString()
  });

  const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload)
    }
  };

  const req = http.request(options, (res) => {
    let data = '';
    res.on('data', (chunk) => { data += chunk; });
    res.on('end', () => {
      console.log(`Audit log sent successfully (Status: ${res.statusCode})`);
      callback();
    });
  });

  req.on('error', (err) => {
    console.warn(`Warning: Could not send audit log (${err.message})`);
    // Continue execution even if audit service is offline
    callback();
  });

  req.write(payload);
  req.end();
}

function run() {
  const databaseUrl = getDatabaseUrl();
  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  const sanitizedDb = sanitizeDatabaseUrl(databaseUrl);
  console.log(`Connected successfully to database: postgres://****:****@${sanitizedDb.host}/${sanitizedDb.database}`);

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  try {
    const files = fs.readdirSync(migrationsDir);
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    // Send audit log first, then list migrations
    sendAuditLog(sanitizedDb, sqlFiles, () => {
      sqlFiles.forEach(file => {
        console.log(file);
      });
    });
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }
}

run();

