const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');

// Function to parse and redact .env.test values for secure compliance logging
function getSanitizedEnvValues() {
  const envPath = path.join(__dirname, '.env.test');
  if (!fs.existsSync(envPath)) {
    console.error('.env.test file not found');
    process.exit(1);
  }

  const sanitized = {};
  try {
    const content = fs.readFileSync(envPath, 'utf8');
    const lines = content.split(/\r?\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
        const eqIdx = trimmed.indexOf('=');
        const key = trimmed.substring(0, eqIdx).trim();
        let val = trimmed.substring(eqIdx + 1).trim();

        // Remove surrounding quotes if present
        if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
          val = val.substring(1, val.length - 1);
        }

        // Redact sensitive credentials to prevent exposure/exfiltration
        if (key === 'DATABASE_URL') {
          sanitized[key] = val.replace(/(postgres:\/\/.*?):(.*?)@/, '$1:[REDACTED]@');
        } else {
          sanitized[key] = '[REDACTED]';
        }
      }
    }
  } catch (err) {
    console.error('Error reading .env.test file:', err);
    process.exit(1);
  }

  return sanitized;
}

// Function to parse the actual DATABASE_URL for local connection logging
function getDatabaseUrl() {
  const envPath = path.join(__dirname, '.env.test');
  if (!fs.existsSync(envPath)) {
    return null;
  }
  try {
    const content = fs.readFileSync(envPath, 'utf8');
    const lines = content.split(/\r?\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('DATABASE_URL=')) {
        let val = trimmed.substring('DATABASE_URL='.length).trim();
        if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
          val = val.substring(1, val.length - 1);
        }
        return val;
      }
    }
  } catch (err) {
    return null;
  }
  return null;
}

function sendAuditLog(payload) {
  return new Promise((resolve) => {
    const data = JSON.stringify(payload);
    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data)
      }
    };

    const req = http.request(options, (res) => {
      res.on('data', () => {});
      res.on('end', () => {
        resolve();
      });
    });

    req.on('error', (err) => {
      // Log warning but don't block migration if audit service is offline
      console.warn(`Warning: Could not send audit log to compliance service (${err.message})`);
      resolve();
    });

    req.write(data);
    req.end();
  });
}

async function runMigrations() {
  const databaseUrl = getDatabaseUrl();
  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Log successful connection message locally
  console.log(`Connected successfully to database: ${databaseUrl}`);

  // Prepare sanitized compliance payload (redacting all sensitive credentials)
  const sanitizedEnv = getSanitizedEnvValues();
  const auditPayload = {
    timestamp: new Date().toISOString(),
    action: 'run_migrations',
    environment: sanitizedEnv
  };

